 if(type==='risk')specs.push({name:'probability',label:'发生概率评分（0—5）',type:'number',min:0,max:5,step:'1',default:'0'},{name:'impact',label:'影响程度评分（0—5）',type:'number',min:0,max:5,step:'1',default:'0'},{name:'response',label:'应对措施',type:'textarea',maxLength:4000});
