$('show-access').addEventListener('click',showAccess);$('context-select').addEventListener('change',()=>{state.contextId=$('context-select').value;state.sequence++;state.project=null;clear($('content'));initialize();});$('show-projects').addEventListener('click',showProjects);$('show-members').addEventListener('click',showMembers);$('show-events').addEventListener('click',showEvents);$('refresh').addEventListener('click',refresh);
